//! DataList options expose actual descendant HTML option records.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><datalist id=datalist>Fallback list<option id=first name=alpha>One</option><span id=nested><option id=second name=beta disabled>Two</option></span></datalist><option id=outside name=outside>Outside</option><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://datalist-options.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn datalist_options_native_canonical_readonly_same_object_and_tree_order(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('datalist'),P=HTMLDataListElement.prototype,a=Object.getOwnPropertyDescriptor(P,'options'),list=x.options;if(!a||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get options'||a.get.length!==0||Object.hasOwn(x,'options')||!(list instanceof HTMLCollection)||Object.getPrototypeOf(list)!==HTMLCollection.prototype||x.options!==list||a.get.call(x)!==list)throw 'canonical readonly same-object options';if(list.length!==2||list.item(0)!==document.getElementById('first')||list[1]!==document.getElementById('second')||list.item(2)!==null||list.namedItem('alpha')!==list[0]||list.namedItem('outside')!==null)throw 'native descendant area tree order and actual names';"#);
}
#[test]
fn datalist_options_inert_namespace_filter_and_live_descendant_mutations(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),ns='http://www.w3.org/1999/xhtml',x=doc.createElementNS(ns,'datalist'),nested=doc.createElementNS(ns,'span'),a=doc.createElementNS(ns,'t:option'),b=doc.createElementNS(ns,'option'),upper=doc.createElementNS(ns,'OPTION'),foreign=doc.createElementNS('urn:foreign','option');a.setAttribute('id','a');b.setAttribute('name','beta');x.appendChild(a);x.appendChild(nested);nested.appendChild(b);nested.appendChild(upper);nested.appendChild(foreign);var list=x.options;if(!(list instanceof HTMLCollection)||list!==x.options||list.length!==2||list[0]!==a||list[1]!==b||list.namedItem('beta')!==b)throw 'exact inert HTML-option descendants';x.insertBefore(b,a);if(list.length!==2||list[0]!==b||list[1]!==a)throw 'live nested option move';x.removeChild(a);if(list.length!==1||list[0]!==b||list.namedItem('a')!==null)throw 'live inert option removal';nested.appendChild(a);if(list.length!==2||list[0]!==b||list[1]!==a)throw 'descendant tree order after reconnect';");
}
#[test]
fn datalist_options_native_live_names_disabled_members_and_ignored_outside_option(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('datalist'),a=document.getElementById('first'),b=document.getElementById('second'),outside=document.getElementById('outside'),list=x.options;a.setAttribute('id','changed');if(list!==x.options||list.length!==2||list[0]!==a||list[1]!==b||list.namedItem('changed')!==a||list.namedItem('first')!==null||list.namedItem('alpha')!==a||list.namedItem('outside')!==null||outside.parentNode!==document.body||!b.hasAttribute('disabled'))throw 'actual live option names and disabled membership';");
}
#[test]
fn datalist_options_exact_native_id_lookup_and_inert_adoption_follow_real_nodes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('datalist'),a=document.getElementById('first'),list=x.options;a.setAttribute('id','A\ud800Z');if(list.namedItem('A\ud800Z')!==a||list.namedItem('A\ufffdZ')!==null)throw 'exact native option ID';var owner=new Document(),other=new Document(),root=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist'),area=owner.createElementNS('http://www.w3.org/1999/xhtml','option');area.setAttribute('name','R\udfffZ');root.appendChild(area);var live=root.options;if(other.adoptNode(root)!==root||root.ownerDocument!==other||area.ownerDocument!==other||root.options!==live||live.length!==1||live[0]!==area||live.namedItem('R\udfffZ')!==area||live.namedItem('R\ufffdZ')!==null)throw 'same inert collection follows actual adoption';"#);
}
#[test]
fn datalist_options_readonly_author_overrides_and_saved_interface_keep_real_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('datalist'),C=HTMLDataListElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'options'),list=x.options;x.options=4;if(x.options!==list||Object.hasOwn(x,'options'))throw 'readonly inherited options';Object.defineProperty(x,'options',{value:'author',configurable:true});if(x.options!=='author'||a.get.call(x)!==list)throw 'author override leaves real collection';delete x.options;delete window.HTMLDataListElement;Object.freeze(P);var b=Object.getOwnPropertyDescriptor(P,'options');if(x.options!==list||b.get!==a.get||b.set!==undefined||b.configurable||!b.enumerable||!(x instanceof C))throw 'saved interface and frozen readonly getter';"#);
}
#[test]
fn datalist_options_accessor_rejects_forged_foreign_and_other_native_brands(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var P=HTMLDataListElement.prototype,a=Object.getOwnPropertyDescriptor(P,'options');for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','datalist'),new Document().createElementNS('http://www.w3.org/1999/xhtml','DATALIST')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'options concrete brand';}var caught=false;try{new a.get();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'options getter illegal construction';");
}
#[test]
fn datalist_options_saved_child_origin_is_checked_before_cached_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('datalist'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var get=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLDataListElement.prototype,'options').get,list=get.call(x);if(list!==x.options||list.length!==2)throw 'captured real options getter';");p.set_location(&crate::navigation::address("https://other-datalist-options.test/",&crate::navigation::Location::home()).unwrap());let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits);p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits),before);p.set_location(&crate::navigation::address("https://datalist-options.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==list||list.length!==2)throw 'saved options origin recovery';");
}
#[test]
fn datalist_options_getter_refusal_is_atomic_and_cached_identity_needs_no_new_filter(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','datalist');"}else{"var x=document.getElementById('datalist');"});let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual DataList handle")};let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.datalist_options_get(object).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom.collections.len(),p.state.dom_commits),before);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();let first=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.datalist_options_get(object).unwrap();let stored=(p.state.retained,p.state.dom.collections.len());p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=1;let second=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.datalist_options_get(object).unwrap();assert_eq!(format!("{first:?}"),format!("{second:?}"));assert_eq!((p.state.retained,p.state.dom.collections.len()),stored);}}
}
